SELECT * FROM review_task
WHERE status = #{status}
ORDER BY created_at DESC

SELECT COUNT(*)
FROM review_task
WHERE owner_name = #{ownerName}
  AND repo_name = #{repoName}
  AND pr_number = #{prNumber}

SELECT * FROM review_task
WHERE owner_name = #{ownerName}
  AND repo_name = #{repoName}
  AND pr_number = #{prNumber}
  AND head_sha = #{headSha}
  AND model_name = #{modelName}
  AND prompt_version = #{promptVersion}
  AND status = 'SUCCESS'
ORDER BY created_at DESC
LIMIT 1
